NPS_API_BASE_URL = "https://developer.nps.gov/api/v1"
REQUEST_TIMEOUT = 30
USER_AGENT = "ClanCal/1.0 NPS Sync"


class NPSAPIError(Exception):
    """Base exception for NPS API integration failures."""


class NPSAPIKeyMissing(NPSAPIError):
    """Raised when no server-side NPS API key is configured."""


class NPSRateLimited(NPSAPIError):
    """Raised when the NPS API key has exceeded its rate limit."""


class NPSAPIClient:
    def __init__(self, api_key: str | None = None) -> None:
        self.api_key = api_key if api_key is not None else settings.NPS_API_KEY

    def get(
        self, endpoint: str, params: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        api_key = str(self.api_key or "").strip()
        if not api_key:
            raise NPSAPIKeyMissing("NPS_API_KEY is not configured.")

        query_string = urlencode(params or {}, doseq=True)
        url = f"{NPS_API_BASE_URL}/{endpoint.lstrip('/')}"

