import logging
from datetime import datetime, time
from typing import Any, TypedDict

from django.db import transaction
from django.utils import timezone

from core.utils import get_system_calendar_user
from trips.models import (
    EventSource,
    NPSAlert,
    NPSCampground,
    NPSPark,
    NPSVisitorCenter,
    RegionCalendar,
    RegionEvent,
    Trip,
    TripRegion,
)
from trips.services.nps_api import NPSAPIClient, NPSAPIKeyMissingError

logger = logging.getLogger(__name__)

OBX_PARK_CODES = ["caha", "wrbr", "fora"]
CAPE_HATTERAS_PARK_CODES = ["caha"]


class SyncStats(TypedDict):
    created: int
    updated: int


class EventSyncStats(TypedDict):
    created: int
    updated: int
    skipped: int
    synced_at: datetime


class SyncResult(TypedDict, total=False):
    parks: SyncStats
    alerts: SyncStats
    visitor_centers: SyncStats
    campgrounds: SyncStats
    events: EventSyncStats
    status: str
    reason: str


def get_obx_region() -> TripRegion | None:
    return (
        TripRegion.objects.filter(slug="outer-banks").first()
        or TripRegion.objects.filter(name__iexact="Outer Banks").first()
        or TripRegion.objects.filter(name__icontains="Outer Banks").first()
    )


def _as_str(value: Any) -> str:
    return str(value or "").strip()


def _source_url(item: dict[str, Any], fallback: str = "") -> str:
    return _as_str(
        item.get("url")
        or item.get("moreInfoUrl")
        or item.get("infourl")
        or item.get("infoUrl")
        or item.get("regresurl")
        or item.get("registrationUrl")
        or fallback
    )


def _event_source_url(item: dict[str, Any]) -> str:
    source_url = _source_url(item)
    if source_url:
        return source_url

    event_id = _as_str(item.get("id"))
    if event_id:
        return f"https://www.nps.gov/planyourvisit/event-details.htm?id={event_id}"
    return ""


def _resource_id(item: dict[str, Any]) -> str:
    return _as_str(
        item.get("id") or item.get("url") or item.get("name") or item.get("title")
    )


def _park_code(item: dict[str, Any]) -> str:
    direct = _as_str(item.get("parkCode") or item.get("sitecode"))
    if direct:
        return direct.lower()
    parks = item.get("parks")
    if isinstance(parks, list) and parks:
        first = parks[0]
        if isinstance(first, dict):
            return _as_str(first.get("parkCode") or first.get("sitecode")).lower()
    return ""


def _float_or_none(value: Any) -> float | None:
    try:
        if value in (None, ""):
            return None
        return float(value)
    except (TypeError, ValueError):
        return None


def _parse_event_datetime(
    date_value: str, time_value: str | None, *, end: bool
) -> datetime:
    parsed_date = datetime.strptime(date_value, "%Y-%m-%d").date()  # noqa: DTZ007
    if time_value:
        for fmt in ("%I:%M %p", "%I %p", "%H:%M:%S", "%H:%M"):
            try:
                parsed_time = datetime.strptime(time_value.strip(), fmt).time()  # noqa: DTZ007
                return timezone.make_aware(datetime.combine(parsed_date, parsed_time))
            except ValueError:
                continue
    return timezone.make_aware(
        datetime.combine(parsed_date, time(23, 59, 59) if end else time.min)
    )


def _event_times(item: dict[str, Any]) -> tuple[str | None, str | None]:
    times = item.get("times")
    if isinstance(times, list) and times:
        first = times[0]
        if isinstance(first, dict):
            return _as_str(first.get("timestart")) or None, _as_str(
                first.get("timeend")
            ) or None
    return _as_str(item.get("timestart")) or None, _as_str(item.get("timeend")) or None


class NPSSyncService:
    def __init__(self, client: NPSAPIClient | None = None) -> None:
        self.client = client or NPSAPIClient()

    def sync_obx(self) -> SyncResult:
        region = get_obx_region()
        if region is None:
            return {"status": "skipped", "reason": "outer_banks_region_missing"}

        try:
            parks = self.sync_parks(region, self.client.get_parks(OBX_PARK_CODES))
            alerts = self.sync_alerts(self.client.get_alerts(OBX_PARK_CODES))
            visitor_centers = self.sync_visitor_centers(
                self.client.get_visitor_centers(OBX_PARK_CODES)
            )
            campgrounds = self.sync_campgrounds(
                self.client.get_campgrounds(CAPE_HATTERAS_PARK_CODES)
            )
            events = self.sync_events(region, self.client.get_events(OBX_PARK_CODES))
        except NPSAPIKeyMissingError:
            logger.info("Skipping NPS sync because NPS_API_KEY is not configured.")
            return {"status": "skipped", "reason": "nps_api_key_missing"}

        return {
            "parks": parks,
            "alerts": alerts,
            "visitor_centers": visitor_centers,
            "campgrounds": campgrounds,
            "events": events,
        }

    def sync_obx_alerts(self) -> dict[str, Any]:
        region = get_obx_region()
        if region is None:
            return {"status": "skipped", "reason": "outer_banks_region_missing"}

        try:
            if not NPSPark.objects.filter(
                region=region, park_code__in=OBX_PARK_CODES
            ).exists():
                self.sync_parks(region, self.client.get_parks(OBX_PARK_CODES))
            alerts = self.sync_alerts(self.client.get_alerts(OBX_PARK_CODES))
        except NPSAPIKeyMissingError:
            logger.info(
                "Skipping NPS alert sync because NPS_API_KEY is not configured."
            )
            return {"status": "skipped", "reason": "nps_api_key_missing"}

        return {"alerts": alerts}

    def sync_parks(
        self, region: TripRegion, items: list[dict[str, Any]]
    ) -> SyncStats:
        now = timezone.now()
        created = 0
        updated = 0
        for item in items:
            park_code = _park_code(item)
            if not park_code:
                continue
            _park, was_created = NPSPark.objects.update_or_create(
                park_code=park_code,
                defaults={
                    "region": region,
                    "full_name": _as_str(item.get("fullName") or item.get("name"))[
                        :255
                    ],
                    "designation": _as_str(item.get("designation"))[:255],
                    "description": _as_str(item.get("description")),
                    "url": _source_url(item)[:2048],
                    "source_url": _source_url(item)[:2048],
                    "raw_data": item,
                    "last_synced_at": now,
                },
            )
            created += int(was_created)
            updated += int(not was_created)
        return {"created": created, "updated": updated}

    def _parks_by_code(self) -> dict[str, NPSPark]:
        return {
            park.park_code: park
            for park in NPSPark.objects.filter(park_code__in=OBX_PARK_CODES)
        }

    def sync_alerts(self, items: list[dict[str, Any]]) -> SyncStats:
        return self._sync_child_records(
            model=NPSAlert,
            related_name="alerts",
            items=items,
            defaults_for_item=lambda item: {
                "title": _as_str(item.get("title"))[:500],
                "description": _as_str(item.get("description")),
                "category": _as_str(item.get("category"))[:100],
                "url": _source_url(item)[:2048],
                "source_url": _source_url(item)[:2048],
                "raw_data": item,
            },
        )

    def sync_visitor_centers(self, items: list[dict[str, Any]]) -> SyncStats:
        return self._sync_child_records(
            model=NPSVisitorCenter,
            related_name="visitor_centers",
            items=items,
            defaults_for_item=lambda item: {
                "name": _as_str(item.get("name") or item.get("title"))[:500],
                "description": _as_str(item.get("description")),
                "url": _source_url(item)[:2048],
                "source_url": _source_url(item)[:2048],
                "latitude": _float_or_none(item.get("latitude")),
                "longitude": _float_or_none(item.get("longitude")),
                "raw_data": item,
            },
        )

    def sync_campgrounds(self, items: list[dict[str, Any]]) -> SyncStats:
        return self._sync_child_records(
            model=NPSCampground,
            related_name="campgrounds",
            items=items,
            defaults_for_item=lambda item: {
                "name": _as_str(item.get("name") or item.get("title"))[:500],
                "description": _as_str(item.get("description")),
                "url": _source_url(item)[:2048],
                "source_url": _source_url(item)[:2048],
                "latitude": _float_or_none(item.get("latitude")),
                "longitude": _float_or_none(item.get("longitude")),
                "raw_data": item,
            },
        )

    def _sync_child_records(
        self, *, model, related_name: str, items, defaults_for_item
    ):
        now = timezone.now()
        parks_by_code = self._parks_by_code()
        seen_by_park: dict[int, set[str]] = {}
        created = 0
        updated = 0

        for item in items:
            park = parks_by_code.get(_park_code(item))
            external_id = _resource_id(item)
            if park is None or not external_id:
                continue
            defaults = defaults_for_item(item)
            defaults.update({"last_synced_at": now, "is_active": True})
            _record, was_created = model.objects.update_or_create(
                park=park,
                external_id=external_id,
                defaults=defaults,
            )
            seen_by_park.setdefault(park.id, set()).add(external_id)
            created += int(was_created)
            updated += int(not was_created)

        deactivated = 0
        for park in parks_by_code.values():
            seen = seen_by_park.get(park.id, set())
            queryset = getattr(park, related_name).filter(is_active=True)
            if seen:
                queryset = queryset.exclude(external_id__in=seen)
            deactivated += queryset.update(is_active=False, last_synced_at=now)

        return {"created": created, "updated": updated, "deactivated": deactivated}

    def sync_events(
        self, region: TripRegion, items: list[dict[str, Any]]
    ) -> EventSyncStats:
        now = timezone.now()
        calendar, _created_calendar = RegionCalendar.objects.get_or_create(
            region=region
        )
        system_user = get_system_calendar_user()
        created = 0
        updated = 0
        skipped = 0

        with transaction.atomic():
            for item in items:
                park_code = _park_code(item)
                external_id = _resource_id(item)
                start_date = _as_str(item.get("datestart") or item.get("dateStart"))
                end_date = _as_str(
                    item.get("dateend") or item.get("dateEnd") or start_date
                )
                if park_code not in OBX_PARK_CODES or not external_id or not start_date:
                    skipped += 1
                    continue

                start_time, end_time = _event_times(item)
                try:
                    start_dt = _parse_event_datetime(start_date, start_time, end=False)
                    end_dt = _parse_event_datetime(
                        end_date or start_date, end_time, end=True
                    )
                except ValueError:
                    skipped += 1
                    continue

                event_source, _created_source = EventSource.objects.get_or_create(
                    source_key=f"nps-{park_code}-events",
                    defaults={
                        "region_calendar": calendar,
                        "name": "National Park Service",
                        "url": "https://www.nps.gov/",
                        "source_type": "API",
                        "default_category": "EVENT",
                    },
                )
                if event_source.region_calendar_id != calendar.id:
                    event_source.region_calendar = calendar
                    event_source.save(update_fields=["region_calendar", "updated_at"])

                _event, was_created = RegionEvent.objects.update_or_create(
                    event_source=event_source,
                    external_id=external_id,
                    defaults={
                        "region_calendar": calendar,
                        "name": _as_str(item.get("title") or item.get("name"))[:255],
                        "description": _as_str(item.get("description")),
                        "start_datetime": start_dt,
                        "end_datetime": end_dt,
                        "location": _as_str(item.get("location"))[:255],
                        "external_url": _event_source_url(item)[:2048],
                        "category": "EVENT",
                        "created_by": system_user,
                        "is_active": True,
                    },
                )
                created += int(was_created)
                updated += int(not was_created)

        return {
            "created": created,
            "updated": updated,
            "skipped": skipped,
            "synced_at": now,
        }


def build_nps_advisory_for_trip(trip: Trip) -> dict[str, Any]:
    region = trip.region
    if region is None:
        return _empty_advisory()

    parks = list(
        NPSPark.objects.filter(region=region)
        .prefetch_related("alerts", "visitor_centers", "campgrounds")
        .order_by("park_code")
    )
    if not parks:
        return _empty_advisory()

    synced_values = [
        value
        for park in parks
        for value in [
            park.last_synced_at,
            *[alert.last_synced_at for alert in park.alerts.all()],
            *[center.last_synced_at for center in park.visitor_centers.all()],
            *[campground.last_synced_at for campground in park.campgrounds.all()],
        ]
        if value is not None
    ]

    return {
        "available": True,
        "parks": [_serialize_park(park) for park in parks],
        "alerts": [
            _serialize_alert(alert)
            for park in parks
            for alert in park.alerts.all()
            if alert.is_active
        ],
        "visitor_centers": [
            _serialize_place(center)
            for park in parks
            for center in park.visitor_centers.all()
            if center.is_active
        ],
        "campgrounds": [
            _serialize_place(campground)
            for park in parks
            for campground in park.campgrounds.all()
            if campground.is_active
        ],
        "last_synced_at": max(synced_values).isoformat() if synced_values else None,
    }


def _empty_advisory() -> dict[str, Any]:
    return {
        "available": False,
        "parks": [],
        "alerts": [],
        "visitor_centers": [],
        "campgrounds": [],
        "last_synced_at": None,
    }


def _serialize_park(park: NPSPark) -> dict[str, Any]:
    return {
        "park_code": park.park_code,
        "full_name": park.full_name,
        "designation": park.designation,
        "description": park.description,
        "url": park.url,
        "source_url": park.source_url,
        "last_synced_at": park.last_synced_at.isoformat()
        if park.last_synced_at
        else None,
    }


def _serialize_alert(alert: NPSAlert) -> dict[str, Any]:
    return {
        "park_code": alert.park.park_code,
        "park_name": alert.park.full_name,
        "title": alert.title,
        "description": alert.description,
        "category": alert.category,
        "url": alert.url,
        "source_url": alert.source_url,
        "last_synced_at": alert.last_synced_at.isoformat()
        if alert.last_synced_at
        else None,
    }


def _serialize_place(place: NPSVisitorCenter | NPSCampground) -> dict[str, Any]:
    return {
        "park_code": place.park.park_code,
        "park_name": place.park.full_name,
        "name": place.name,
        "description": place.description,
        "url": place.url,
        "source_url": place.source_url,
        "latitude": place.latitude,
        "longitude": place.longitude,
        "last_synced_at": place.last_synced_at.isoformat()
        if place.last_synced_at
        else None,
    }
